# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİN KAVRAMININ ETiMOLOJİSİ VE İSLAM ÂLİMLERİNE GÖRE TANIMI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Din Kelimesinin Sözlük Anlamları</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">• Boyun eğmek, itaat ve teslimiyet</text>\n  <text x="50" y="130" font-size="11.5" fill="#334155">• Hüküm, kanun, şeriat ve yönetim</text>\n  <text x="50" y="155" font-size="11.5" fill="#334155">• Hesap, ceza, mükâfat ve karşılık</text>\n  <text x="62" y="173" font-size="11" fill="#475569">(&quot;Yevmü\'d-dîn&quot; = Hesap/Din günü)</text>\n  <text x="50" y="200" font-size="11.5" fill="#334155">• Yol, âdet, millet ve yaşam biçimi</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Klasik İslami Tanımın 4 Temel Unsuru</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">1. Kaynak: Allah (c.c.) tarafından vahiy ve</text>\n  <text x="392" y="123" font-size="11" fill="#475569">peygamberler aracılığıyla konulmuş ilahi kanun.</text>\n  <text x="380" y="148" font-size="11.5" fill="#334155">2. Muhatap: Akıl ve irade sahibi insanlar.</text>\n  <text x="380" y="173" font-size="11.5" fill="#334155">3. Yöntem: Kendi hür irade ve hüsn-i</text>\n  <text x="392" y="191" font-size="11" fill="#475569">ihtiyarlarıyla (zorlama olmaksızın) seçmeleri.</text>\n  <text x="380" y="216" font-size="11.5" font-weight="bold" fill="#166534">4. Amaç: Dünya ve ahiret mutluluğu (felah).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FARKLI BİLİM DALLARININ VE DİSİPLİNLERİN DİNE YAKLAŞIMLARI</text>\n  <rect x="20" y="50" width="155" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="97" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Teoloji / İlahiyat</text>\n  <text x="30" y="103" font-size="10.5" fill="#334155">• Dini içeriden ve</text>\n  <text x="35" y="120" font-size="10.5" fill="#334155">kutsal metinleri</text>\n  <text x="35" y="137" font-size="10.5" fill="#334155">esas alarak inceler.</text>\n  <text x="30" y="165" font-size="10.5" font-weight="bold" fill="#1e40af">Normatif (kural</text>\n  <text x="30" y="182" font-size="10.5" font-weight="bold" fill="#1e40af">koyucu) ve savunucu</text>\n  <text x="30" y="199" font-size="10.5" fill="#334155">bir yaklaşım izler.</text>\n  <rect x="188" y="50" width="155" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="265" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Din Sosyolojisi</text>\n  <text x="198" y="103" font-size="10.5" fill="#334155">• Din ile toplum</text>\n  <text x="203" y="120" font-size="10.5" fill="#334155">arasındaki karşılıklı</text>\n  <text x="203" y="137" font-size="10.5" fill="#334155">etkileşimi inceler.</text>\n  <text x="198" y="165" font-size="10.5" fill="#334155">• Dini gruplar, kurumlar</text>\n  <text x="203" y="182" font-size="10.5" fill="#334155">ve toplumsal bütünleşme</text>\n  <text x="203" y="199" font-size="10.5" font-weight="bold" fill="#166534">üzerine odaklanır.</text>\n  <rect x="356" y="50" width="155" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="433" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Din Psikolojisi</text>\n  <text x="366" y="103" font-size="10.5" fill="#334155">• Dinin bireyin iç</text>\n  <text x="371" y="120" font-size="10.5" fill="#334155">dünyasındaki (duygu,</text>\n  <text x="371" y="137" font-size="10.5" fill="#334155">düşünce, tutum) yerini.</text>\n  <text x="366" y="165" font-size="10.5" fill="#334155">• Dua, tövbe ve dini</text>\n  <text x="371" y="182" font-size="10.5" fill="#334155">tecrübenin ruh sağlığına</text>\n  <text x="371" y="199" font-size="10.5" font-weight="bold" fill="#b45309">etkisini araştırır.</text>\n  <rect x="524" y="50" width="155" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="601" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">Antropoloji &amp; Felsefe</text>\n  <text x="534" y="103" font-size="10.5" fill="#334155">• Antropoloji: Kültür,</text>\n  <text x="539" y="120" font-size="10.5" fill="#334155">sembol ve ritüelleri</text>\n  <text x="539" y="137" font-size="10.5" fill="#334155">tarihsel boyutta inceler.</text>\n  <text x="534" y="165" font-size="10.5" fill="#334155">• Din Felsefesi: Dinin</text>\n  <text x="539" y="182" font-size="10.5" fill="#334155">temel iddialarını akıl</text>\n  <text x="539" y="199" font-size="10.5" font-weight="bold" fill="#991b1b">ve mantıkla sorgular.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAYNAKLARINA GÖRE DİNLER VE DİNİN EVRENSEL İŞLEVLERİ</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kaynağına Göre Dinlerin Tasnifi</text>\n  <text x="50" y="110" font-size="11.5" font-weight="bold" fill="#1e40af">1. Vahye Dayalı (İlahi / Semavi) Dinler:</text>\n  <text x="62" y="128" font-size="11" fill="#334155">• Kaynağı Allah\'ın vahyidir (Yahudilik,</text>\n  <text x="62" y="146" font-size="11" fill="#334155">Hristiyanlık ve son hak din İslamiyet).</text>\n  <text x="50" y="175" font-size="11.5" font-weight="bold" fill="#1e40af">2. Beşerî (Tabii / Geleneksel) Dinler:</text>\n  <text x="62" y="193" font-size="11" fill="#334155">• İnsan düşünce ve geleneğiyle oluşmuştur</text>\n  <text x="62" y="211" font-size="11" fill="#334155">(Hinduizm, Budizm, Konfüçyanizm, Taoizm).</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Dinin Birey ve Toplum Hayatındaki Rolü</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Bireyin &quot;Nereden geldim, niçin varım, nereye</text>\n  <text x="392" y="128" font-size="11" fill="#475569">gideceğim?&quot; varoluşsal sorularına anlam verir.</text>\n  <text x="380" y="155" font-size="11.5" fill="#334155">• Kutsal (sacred) ve dünyevi (profan) ayrımıyla</text>\n  <text x="392" y="173" font-size="11" fill="#475569">ahlaki değerleri ve adalet bilincini korur.</text>\n  <text x="380" y="200" font-size="11.5" fill="#334155">• Bilim, felsefe ve sanatın gelişimine ilham verir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
